function canReach(furniture, d) {
  const V = furniture.length;
  const graph = Array(V)
    .fill()
    .map(() => []);
  for (let i = 0; i < V; i++) {
    for (let j = i + 1; j < V; j++) {
      if (distance(furniture[i], furniture[j]) <= d) {
        graph[i].push(j);
        graph[j].push(i);
      }
    }
  }

  const visited = new Set([0]);

  function visit(node) {
